const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([-9.8, 35.5, -0.5, 38.9]); // Southern Spain broad bbox
    const start = '2023-04-01';
    const end = '2023-05-01';
    const scale = 9000; // >=3000 as per best practices

    // 2. Data Acquisition & Check with fallback
    let datasetUsed = null;
    let imgCount = 0;
    let maxF = null;

    // Primary: ERA5-Land Hourly (2m air temperature)
    try {
      let colH = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
        .filterDate(start, end)
        .select('temperature_2m');
      imgCount = await colH.size().getInfo();
      if (imgCount > 0) {
        const colHF = colH.map(function(img) {
          const f = img.select('temperature_2m').subtract(273.15).multiply(9.0/5.0).add(32).rename('t2mF');
          return f.copyProperties(img, img.propertyNames());
        });
        maxF = colHF.max(); // monthly per-pixel max in F
        datasetUsed = 'ECMWF/ERA5_LAND/HOURLY';
      }
    } catch (e) {
      // fall through to fallback
    }

    // Fallback: ERA5-Land Daily Aggregated (daily max 2m temp)
    if (!maxF) {
      try {
        let colD = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
          .filterDate(start, end)
          .select('temperature_2m_max');
        imgCount = await colD.size().getInfo();
        if (imgCount > 0) {
          const colDF = colD.map(function(img) {
            const f = img.select('temperature_2m_max').subtract(273.15).multiply(9.0/5.0).add(32).rename('t2mF');
            return f.copyProperties(img, img.propertyNames());
          });
          maxF = colDF.max();
          datasetUsed = 'ECMWF/ERA5_LAND/DAILY_AGGR';
        }
      } catch (e2) {
        // continue
      }
    }

    if (!maxF) {
      console.log('Collection: 0 images (both hourly and daily)');
      console.log('C1');
      return;
    }

    console.log(`Dataset: ${datasetUsed}, Images: ${imgCount}`);

    // 3. Processing & Validation
    // Total valid pixels
    const totalCount = await ee.Number(
      maxF.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('t2mF')
    ).getInfo();

    if (!totalCount || totalCount === 0) {
      console.log('Valid Pixels: 0');
      console.log('C2');
      return;
    }

    // Regional max temperature (F)
    const regionalMaxF = await ee.Number(
      maxF.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('t2mF')
    ).getInfo();

    if (regionalMaxF === null || isNaN(regionalMaxF)) {
      console.log(`MaxF: ${regionalMaxF}`);
      console.log('C3');
      return;
    }

    // Count pixels exceeding 90 F
    const hotMask = maxF.gt(90);
    const hotCount = await ee.Number(
      hotMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('t2mF')
    ).getInfo();

    const pct = totalCount > 0 ? (100.0 * (hotCount || 0) / totalCount) : 0;

    // 4. Evidence (concise)
    console.log(`Valid Pixels: ${totalCount}`);
    console.log(`Regional Max Temp (F): ${regionalMaxF.toFixed(2)}`);
    console.log(`Pixels >90F: ${hotCount || 0}/${totalCount} (${pct.toFixed(2)}%)`);

    // 5. Final Answer
    if (regionalMaxF > 90) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.log(`Init Error: ${e && e.message ? e.message : e}`);
    console.log('D');
  }
}

initEE();
